#include <stdlib.h>
#include <string.h>
int mn(int a, int b)  {
    return a < b ? a : b;
}
int mx(int a, int b)  {
    return a > b ? a : b;
}
int read(void)  {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a)  {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x)  {
    printf("%d ", x);
}
void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int i = 0, k = 0, n = 0, x = 0;
    // 本平台用数值序列表示链表，已知长度后可直接换算倒数位置。
    n = read();
    k = read();
    for (i = 0; i < n; i += 1)  {
        x = read();
        // 倒数第 k 个的零起点下标是 n-k，只略过这个位置。
        if (i != (n - k))  {
            // 其余数值原顺序输出；不要附加长度或空序列标记。
            emit(x);
        }
    }
    return 0;
}

